function icon(key){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[key]||icons.file}"/></svg>`;}
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const states=['待分配','已分配','检验中','已提交','已复核','已批准','OOS候选'];
const tasks=[
{id:'TJ-026',sample:'YP-0929-001',material:'原料药 A',batch:'26092901',item:'含量测定',method:'高效液相色谱法',status:'检验中',due:'今天 16:00',priority:'优先',progress:2,total:5,owner:'检验员 A',result:'',log:[]},
{id:'TJ-027',sample:'YP-0929-002',material:'原料药 A',batch:'26092902',item:'水分',method:'水分测定法',status:'已分配',due:'今天 17:00',priority:'常规',progress:0,total:3,owner:'检验员 A',result:'',log:[]},
{id:'TJ-028',sample:'YP-0929-003',material:'注射用粉针 B',batch:'26092903',item:'鉴别',method:'红外光谱法',status:'已提交',due:'今天 17:30',priority:'常规',progress:3,total:3,owner:'检验员 A',result:'符合',log:[]},
{id:'TJ-029',sample:'YP-0928-009',material:'原料药 A',batch:'26092809',item:'含量测定',method:'高效液相色谱法',status:'OOS候选',due:'昨天 15:00',priority:'紧急',progress:4,total:5,owner:'检验员 A',result:'97.20',log:[]},
{id:'TJ-030',sample:'YP-0929-005',material:'包材 C',batch:'26092905',item:'外观',method:'目视检查',status:'待分配',due:'明天 10:00',priority:'常规',progress:0,total:2,owner:'待分配',result:'',log:[]},
{id:'TJ-031',sample:'YP-0928-006',material:'原料药 A',batch:'26092806',item:'含量测定',method:'高效液相色谱法',status:'已复核',due:'明天 14:00',priority:'常规',progress:5,total:5,owner:'检验员 A',result:'99.40',log:[]},
{id:'TJ-032',sample:'YP-0927-011',material:'注射用粉针 B',batch:'26092711',item:'鉴别',method:'红外光谱法',status:'已批准',due:'昨天 11:00',priority:'常规',progress:3,total:3,owner:'检验员 A',result:'符合',log:[]}
];
const navGroups=[['我的工作',[['dashboard','今日工作','home'],['tasks','我的检验','flask'],['review','复核与批准','shield']]],['检验业务',[['samples','样品管理','sample'],['results','检验结果','file'],['reports','检验报告','book']]],['专项管理',[['retention','留样管理','box'],['stability','稳定性考察','chart']]],['标准与追溯',[['specs','质量标准','book'],['ledger','受控台账','layers'],['audit','审计追踪','history'],['modules','全部功能','grid']]]];
const titles=Object.fromEntries(navGroups.flatMap(g=>g[1]).map(n=>[n[0],n[1]]));titles.entry='检验结果录入';titles.register='样品登记';
let state={page:'dashboard',tab:'',status:'全部状态',q:'',persona:'analyst',selected:'TJ-026',ledger:'TJ-028',viewState:'data',urgent:false,draft:{},draftTime:'',reviewFilter:'pending'};
const main=document.getElementById('main');const dialog=document.getElementById('dialog');let lastFocus=null,toastTimer;
const tag=(text,tone='')=>`<span class="tag ${tone}">${escapeHtml(text)}</span>`;
const stateTag=status=>tag(status,({'待分配':'amber','已分配':'blue','检验中':'blue','已提交':'amber','已复核':'blue','已批准':'green','OOS候选':'red'})[status]);
function btn(label,attrs='',primary=false,ic=''){return `<button class="btn ${primary?'primary':''}" ${attrs}>${ic?icon(ic):''}${label}</button>`;}
function quiet(label,attrs=''){return `<button class="btn quiet" ${attrs}>${label}${icon('chevron')}</button>`;}
function taskAction(t){return t.status==='已分配'?'开始检验':t.status==='检验中'?'继续检验':'查看结果';}
function dataTask(t){return `data-task="${t.id}"`;}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3800);}
function openDialog(title,html){lastFocus=document.activeElement;document.getElementById('dialog-title').textContent=title;document.getElementById('dialog-body').innerHTML=html;hydrateIcons();if(!dialog.open)dialog.showModal();}
function closeDialog(){dialog.close();if(lastFocus?.isConnected)lastFocus.focus();}
function navigate(page,options={}){state.page=page;state.tab='';state.status='全部状态';state.q='';state.urgent=false;state.viewState='data';Object.assign(state,options);writeHash();render();window.scrollTo({top:0});main.focus({preventScroll:true});}
function writeHash(){const params=new URLSearchParams();if(state.status!=='全部状态')params.set('status',state.status);if(state.tab)params.set('tab',state.tab);if(state.q)params.set('q',state.q);history.replaceState(null,'',`#${state.page}${params.size?'?'+params:''}`);}
function renderNav(){document.getElementById('navigation').innerHTML=navGroups.map(([label,items])=>`<div class="nav-group-label">${label}</div>${items.map(([key,title,ic])=>`<button class="nav-item ${state.page===key||(key==='tasks'&&state.page==='entry')?'active':''}" data-page="${key}" aria-label="${title}" ${state.page===key?'aria-current="page"':''}>${icon(ic)}<span>${title}</span>${key==='tasks'?`<b class="count">${tasks.filter(t=>['已分配','检验中'].includes(t.status)).length}</b>`:''}</button>`).join('')}`).join('');document.querySelectorAll('.mobile-nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===state.page);if(b.dataset.page===state.page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});}
const descriptions={dashboard:'每一次检验，都从清晰的下一步开始。',tasks:'按截止时间安排检验，进度与下一步一目了然。',samples:'从样品登记到检验放行，保留完整的样品上下文。',results:'检验项目、冻结限度与结果记录，集中查看。',review:'先核对检验依据，再形成复核与批准意见。',entry:'核对样品、输入结果、检查依据，然后提交。',register:'一次登记样品信息，并确认采用的标准与检验项目。',ledger:'查阅受控结果、签署与修订，沿着记录追溯。',reports:'从检验结果到检验报告，查看审核与发布进度。',specs:'按物料查阅标准版本、检验项目和限度。',retention:'关注应观察、待审核与临期处理的留样。',stability:'将取样时间点、检测计划与结果趋势连接起来。',audit:'按记录或操作人追溯检验活动。',modules:'按工作领域查找功能，日常任务从「我的检验」开始。'};
function header(){let actions='';if(state.page==='dashboard')actions=`<span class="date-label">${icon('calendar')}2026年9月29日 · 星期二</span>`;else if(state.page==='samples')actions=btn('登记样品','data-page="register"',true,'plus');else if(state.page==='entry'||state.page==='register')actions=btn('返回列表',`data-page="${state.page==='entry'?'tasks':'samples'}"`,false,'arrow-left');else actions=`<span class="tag">${state.persona==='analyst'?'我的检验工作':state.persona==='reviewer'?'我的复核工作':'我的质量工作'}</span>`;return `<div class="page-top"><div><div class="breadcrumbs">实验室管理 ${icon('chevron')} <span>${titles[state.page]||'今日工作'}</span></div><h1>${titles[state.page]||'今日工作'}</h1><p>${descriptions[state.page]||''}</p></div><div class="head-actions">${actions}</div></div>`;}
function metric(label,value,foot,ic,target,filter=''){return `<button class="stat" data-page="${target}" ${filter?`data-filter="${filter}"`:''}><span class="stat-label">${label}${icon(ic)}</span><strong>${value}</strong><small>项</small><div class="stat-foot">${foot}</div></button>`;}
function processStrip(current=2){return `<div class="route-strip">${['任务分配','开展检验','提交结果','复核','批准'].map((s,i)=>`${i?'<i></i>':''}<div class="route-stage ${i<current?'done':i===current?'current':''}"><b>${i<current?'✓':i+1}</b><span>${s}</span></div>`).join('')}</div>`;}
function smallTask(t){return `<article class="task-row"><span class="sample-icon">${icon('sample')}</span><div><h3>${t.material} · ${t.item}${stateTag(t.status)}</h3><p>${t.sample}　·　批次 ${t.batch}</p><div class="task-progress" aria-label="完成 ${t.progress}/${t.total} 个项目"><span style="width:${t.progress/t.total*100}%"></span></div></div><div><small>${t.due}　${t.progress}/${t.total} 项完成</small>${btn(taskAction(t),dataTask(t),t.status==='检验中')}</div></article>`;}
function dashboard(){const pending=tasks.filter(t=>['已分配','检验中'].includes(t.status));const count=s=>tasks.filter(t=>t.status===s).length;return `<section class="hero"><div class="hero-copy"><div class="eyebrow">${icon('flask')}上午好，${{analyst:'检验员 A',reviewer:'复核员 B',qa:'质量人员 C'}[state.persona]}</div><h2>${state.persona==='analyst'?'把今天的检验，<br>安排得更从容。':'让每一份结果，<br>有依据、可追溯。'}</h2><p>${state.persona==='analyst'?`你有 ${pending.length} 项检验待处理。先完成临近截止的任务。`:'从待办进入记录，核对结果、原始记录与签署。'}</p><div>${btn(state.persona==='analyst'?'继续检验':'查看待办',state.persona==='analyst'?'data-task="TJ-026"':'data-page="review"',true,'arrow')}<span class="hero-badge">${icon('clock')} 今天优先处理</span></div></div><img class="hero-art" src="assets/实验室.svg" alt="色谱仪、锥形瓶与样品瓶的实验室插画"></section>
<div class="mini-stats">${metric('待检',count('已分配')+count('待分配'),'按截止时间依次开展','sample','tasks','已分配')}${metric('检验中',count('检验中'),'接着完成当前记录','flask','tasks','检验中')}${metric('待复核',count('已提交'),'已提交，等待复核','shield','review')}${metric('待发布报告',2,'查看审核与发布条件','file','reports')}</div>
<div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><div><h2>接下来要做</h2><p>把样品、进度和下一步放在一起</p></div>${quiet('全部任务','data-page="tasks"')}</div><div class="task-tabs"><button class="${state.tab!=='attention'?'active':''}" data-tab="today">今日待办 <b>${pending.length}</b></button><button class="${state.tab==='attention'?'active':''}" data-tab="attention">需关注 <b>1</b></button></div>${(state.tab==='attention'?tasks.filter(t=>t.status==='OOS候选'):pending).map(smallTask).join('')||empty('当天待办已处理完','可查看全部检验任务或安排后续工作。','tasks','查看任务')}</section>
<section class="panel"><div class="panel-head"><div><h2>这份样品，进行到哪一步了？</h2><p>YP-0929-001 · 原料药 A · 批次 26092901</p></div>${quiet('详情','data-detail="YP-0929-001" data-kind="samples"')}</div>${processStrip(tasks[0].status==='已提交'?2:1)}<div class="note">${icon('flask')} 当前${tasks[0].status==='已提交'?'结果已提交，等待复核。':'正在检验，已完成 2 / 5 个项目。下一个项目：含量测定。'}</div></section>
<section class="panel"><div class="panel-head"><h2>常用操作</h2><span class="muted view-count">少找一步，更快开始</span></div><div class="quick-grid"><button data-page="register">${icon('plus')}登记样品</button><button data-page="specs">${icon('book')}查阅标准</button><button data-page="ledger">${icon('history')}追溯记录</button></div></section></div>
<aside class="dashboard-side"><section class="panel"><div class="panel-head"><h2>当前样品</h2><span class="tag blue">检验中</span></div><div class="sample-label"><header>海滨实验室 · 样品标签${icon('sample')}</header><h3>原料药 A</h3><p>批号 26092901　/　含量测定</p><div class="barcode" aria-hidden="true"></div><small>YP-0929-001</small></div>${quiet('查看检验依据','data-detail="YP-0929-001" data-kind="samples"')}</section>
<section class="panel"><div class="panel-head"><h2>实验室日程</h2>${icon('calendar')}</div><div class="next-event"><div class="event-date"><b>29</b>今天</div><div><h3>稳定性 · 6 月取样</h3><p>原料药 A · 14:00 前</p>${quiet('查看计划','data-page="stability" data-tab-target="schedule"')}</div></div><div class="next-event"><div class="event-date"><b>30</b>明天</div><div><h3>留样 · 外观观察</h3><p>注射用粉针 B · 3 份留样</p>${quiet('查看观察任务','data-page="retention" data-tab-target="observations"')}</div></div></section><div class="status-foot">检验有序 · 记录清晰 · 结果可追溯</div></aside></div>`;}
function empty(title,desc,page='',label='返回工作台'){return `<div class="empty-state">${icon('sample')}<h3>${title}</h3><p>${desc}</p>${page?btn(label,`data-page="${page}"`,true):''}</div>`;}
function filteredTasks(){return tasks.filter(t=>(state.status==='全部状态'||t.status===state.status)&&(!state.q||`${t.id} ${t.sample} ${t.material} ${t.batch} ${t.item}`.toLowerCase().includes(state.q.toLowerCase()))&&(!state.urgent||t.due.startsWith('今天')));}
function filterBar(){return `<div class="toolbar"><form class="search-field" id="list-search">${icon('search')}<input name="q" aria-label="筛选样品或批次" placeholder="输入样品号、批次、检验项目" value="${escapeHtml(state.q)}"><button class="icon-btn" aria-label="搜索">${icon('arrow')}</button></form><div class="actions">${btn(state.urgent?'显示全部日期':'只看今日到期','data-action="urgent"',state.urgent,'clock')}${btn('重置筛选','data-action="reset"',false,'refresh')}</div></div>`;}
function taskBoard(){const list=filteredTasks();return `${filterBar()}<div class="status-filter" aria-label="检验任务状态">${['全部状态',...states].map(s=>`<button class="${state.status===s?'active':''}" data-status="${s}" aria-pressed="${state.status===s}">${s==='OOS候选'?'超标候选（OOS）':s}<b>${s==='全部状态'?tasks.length:tasks.filter(t=>t.status===s).length}</b></button>`).join('')}</div><label class="mobile-state">任务状态<select id="status-select">${['全部状态',...states].map(s=>`<option ${state.status===s?'selected':''}>${s}</option>`).join('')}</select></label><div class="panel"><div class="panel-head"><h2>${state.status==='全部状态'?'我的检验任务':state.status}</h2><span class="view-count">${list.length} 项 · 演示截止时间顺序</span></div>${list.length?`<div class="table-wrap desktop-data"><table class="data-table"><thead><tr><th>样品 / 检验项目</th><th>批次</th><th>当前状态</th><th>截止时间</th><th>下一步</th></tr></thead><tbody>${list.map(t=>`<tr><td><strong>${t.material} · ${t.item}</strong><small>${t.sample} / ${t.id}</small></td><td>${t.batch}<small>${t.owner}</small></td><td>${stateTag(t.status)}<small>${t.status==='已提交'?'等待复核':t.status==='已复核'?'等待批准':t.status==='OOS候选'?'需质量核查':t.progress+'/'+t.total+' 个项目完成'}</small></td><td>${t.due}<small>${t.priority}</small></td><td>${btn(taskAction(t),dataTask(t),t.status==='检验中')}</td></tr>`).join('')}</tbody></table></div><div class="mobile-cards">${list.map(t=>`<article class="mobile-card"><header><h3>${t.material} · ${t.item}</h3>${stateTag(t.status)}</header><p>${t.sample} · 批次 ${t.batch}</p><p>负责人：${t.owner}　已完成 ${t.progress}/${t.total} 项</p><footer><span>${t.due}</span>${btn(taskAction(t),dataTask(t),t.status==='检验中')}</footer></article>`).join('')}</div>`:empty('没有匹配的任务','试试其他状态，或重置筛选条件。')}${!list.length?btn('重置筛选','data-action="reset"'):''}</div>`;}
function samples(){const list=filteredTasks();return `${filterBar()}<section class="panel"><div class="panel-head"><h2>样品台账</h2><span class="view-count">${list.length} 份样品 · 状态与项目进度</span></div><div class="table-wrap desktop-data"><table class="data-table"><thead><tr><th>样品 / 物料</th><th>批次</th><th>质量标准</th><th>样品状态</th><th>项目进度</th><th></th></tr></thead><tbody>${list.map(t=>`<tr><td><strong>${t.sample}</strong><small>${t.material}</small></td><td>${t.batch}</td><td>${t.material==='原料药 A'?'ZL-A / 第3版':'对应物料标准'}</td><td>${tag(t.status==='已批准'?'检验完成':t.status==='待分配'?'已登记':'检验中',t.status==='已批准'?'green':'blue')}</td><td>${t.progress}/${t.total}<div class="task-progress"><span style="width:${t.progress/t.total*100}%"></span></div></td><td>${quiet('查看',`data-detail="${t.sample}" data-kind="samples"`)}</td></tr>`).join('')}</tbody></table></div><div class="mobile-cards">${list.map(t=>`<article class="mobile-card"><header><h3>${t.material}</h3>${tag(t.status==='已批准'?'检验完成':'检验中','blue')}</header><p>${t.sample} · 批次 ${t.batch}</p><footer><span>已完成 ${t.progress}/${t.total} 项</span>${quiet('样品详情',`data-detail="${t.sample}" data-kind="samples"`)}</footer></article>`).join('')}</div>${!list.length?empty('没有匹配的样品','请核对样品号或批次。'):''}</section>`;}
function register(){return `<form id="register-form"><div class="result-layout"><section class="panel"><div class="panel-head"><h2>样品基础信息</h2>${tag('登记前核对','amber')}</div><div class="form-grid"><label class="form-field">物料名称 <em>必填</em><select name="material"><option>原料药 A</option><option>注射用粉针 B</option><option>包材 C</option></select></label><label class="form-field">批次编号 <em>必填</em><input name="batch" required placeholder="请输入批次编号" pattern="[A-Za-z0-9-]+"></label><label class="form-field">样品类型<select name="type"><option>原料</option><option>成品</option><option>包材</option></select></label><label class="form-field">送样来源<select><option>生产送检</option><option>来料送检</option></select></label><label class="form-field">优先级<select><option>常规</option><option>优先</option></select></label><label class="form-field">计划完成时间<input type="date" value="2026-09-30"></label><label class="form-field full">送样说明<textarea rows="3" placeholder="填写与样品相关的补充说明"></textarea></label></div></section><aside><section class="panel"><h2>采用的质量标准</h2><div class="note">本页仅演示标准确认步骤。正式登记时，标准由物料与后端登记规则确定。</div><h3>原料药 A · 质量标准</h3><dl class="context-list"><div><dt>版本</dt><dd>ZL-A · 第 3 版</dd></div><div><dt>状态</dt><dd>${tag('已生效','green')}</dd></div><div><dt>检验项目</dt><dd>含量 / 水分 / 鉴别</dd></div></dl>${quiet('查看标准','data-detail="ZL-A · 第3版" data-kind="specs"')}</section><section class="panel"><h3>登记后冻结</h3><p class="note">登记时保存检验项目与标准限度快照。后续标准变更不覆盖这份样品的检验依据。</p></section></aside></div><div class="action-bar"><p>${icon('lock')} 请确认样品与批次对应无误</p><div class="actions">${btn('取消','type="button" data-page="samples"')}${btn('确认登记','type="submit"',true,'check')}</div></div></form>`;}
function results(){const list=tasks.filter(t=>t.result||t.status==='检验中').filter(t=>!state.q||`${t.sample} ${t.batch} ${t.material}`.includes(state.q));return `${filterBar()}<section class="panel"><div class="panel-head"><h2>检验结果清单</h2><span class="view-count">结果值与冻结限度并列</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>样品 / 项目</th><th>结果值</th><th>冻结限度</th><th>结果状态</th><th>记录</th></tr></thead><tbody>${list.map(t=>`<tr><td><strong>${t.sample}</strong><small>${t.material} · ${t.item}</small></td><td><strong class="${t.status==='OOS候选'?'outlier':''}">${t.result||'待录入'}${t.item==='含量测定'&&t.result?' %':''}</strong></td><td>${t.item==='含量测定'?'98.00% – 102.00%':'按冻结标准'}<small>${t.item==='含量测定'?'ZL-A 第3版':'对应项目快照'}</small></td><td>${stateTag(t.status==='OOS候选'?'已提交':t.status==='检验中'?'草稿':t.status)}${t.status==='OOS候选'?'<small class="outlier">超标候选（OOS）</small>':''}</td><td>${quiet(t.status==='检验中'?'继续录入':'查看依据',dataTask(t))}</td></tr>`).join('')}</tbody></table></div>${!list.length?empty('没有匹配的结果','请尝试其他样品号或批次。'):''}</section>`;}
function entry(){const t=tasks.find(t=>t.id===state.selected)||tasks[0];const d=state.draft[t.id]||{};return `<div class="panel"><div class="panel-head"><h2>${t.material} · ${t.item}</h2>${stateTag(t.status)}</div><p class="muted">${t.sample}　/　批次 ${t.batch}　/　${t.id}</p>${processStrip(1)}</div><form id="entry-form"><div class="result-layout"><div><section class="panel"><div class="panel-head"><h2>填写检验结果</h2><span class="pill-check">${icon('lock')}标准已冻结</span></div><div class="method-card">${icon('flask')}<div><strong>${t.method}</strong><small>质量标准 ZL-A · 第 3 版　/　示例有效位数：2 位小数</small></div></div><div class="form-grid"><label class="form-field">原始读数 <em>必填</em><input id="raw-value" name="raw" value="${escapeHtml(d.raw||'0.4982')}" required inputmode="decimal"></label><label class="form-field">结果值 <em>必填</em><div class="input-unit"><input id="result-value" name="result" value="${escapeHtml(d.result||'99.40')}" type="number" step="0.01" required inputmode="decimal"><span>%</span></div></label><label class="form-field full">检验仪器 / 编号<input name="instrument" value="${escapeHtml(d.instrument||'HPLC-03')}" placeholder="记录本次使用的仪器"></label></div><div class="limit-panel"><div class="limit-header"><strong>冻结限度 98.00% – 102.00%</strong><span id="range-tag" class="tag green">限度内 · 录入参考</span></div><div class="limit-scale"><i id="limit-pointer" class="limit-pointer"></i></div><div class="scale-labels"><span>97.00%</span><span>98.00%</span><span>102.00%</span><span>103.00%</span></div></div><p id="range-note" class="state-note">数值与限度对照仅作录入参考，正式判定由 LIMS 计算。</p><label class="form-field full" style="margin-top:18px">检验说明 / 异常说明<textarea name="comment" rows="3" placeholder="填写与本次检验有关的说明">${escapeHtml(d.comment||'')}</textarea></label></section><section class="panel"><div class="panel-head"><h2>原始记录与附件</h2><span class="view-count">演示附件</span></div><button type="button" class="record-button" data-action="record">${icon('file')}<span><strong>${t.item}原始记录</strong><small>${t.sample} · 查看记录与色谱图示意</small></span>${icon('chevron')}</button></section></div><aside><section class="panel"><h2>样品与检验依据</h2><dl class="context-list"><div><dt>样品编号</dt><dd>${t.sample}</dd></div><div><dt>批次</dt><dd>${t.batch}</dd></div><div><dt>检验项目</dt><dd>${t.item}</dd></div><div><dt>分析员</dt><dd>${t.owner}</dd></div><div><dt>标准版本</dt><dd>ZL-A · 第3版</dd></div><div><dt>截止时间</dt><dd>${t.due}</dd></div></dl>${quiet('查看样品上下文',`type="button" data-detail="${t.sample}" data-kind="samples"`)}</section><section class="panel"><h2>签署进度</h2>${signature('检验员 A','正在录入','blue')}${signature('复核员','等待提交','')}${signature('批准人','等待复核','')}<p class="note">复核人与检验人不同；批准人与检验人、复核人均不同。</p></section></aside></div><div class="action-bar"><p id="save-hint">${state.draftTime?'本页暂存于 '+state.draftTime:'填写完成后，先核对再提交'}</p><div class="actions">${btn('暂存本页','type="button" data-action="save"',false,'save')}${btn('核对并提交','type="submit"',true,'check')}</div></div></form>`;}
function entrySpec(t){
  if(t.item==='含量测定')return {method:'高效液相色谱法',unit:'%',min:98,max:102,raw:'0.4982',result:'99.40',limit:'98.00% – 102.00%',labels:['97.00%','98.00%','102.00%','103.00%'],numeric:true};
  if(t.item==='水分')return {method:'水分测定法',unit:'%',min:0,max:1,raw:'0.42',result:'0.42',limit:'≤ 1.00%',labels:['0.00%','0.50%','1.00%','1.20%'],numeric:true};
  return {method:t.method,unit:'',min:null,max:null,raw:'',result:'符合规定',limit:'按冻结标准判定',labels:[],numeric:false};
}
function entryV2(){const t=tasks.find(t=>t.id===state.selected)||tasks[0];const d=state.draft[t.id]||{};const cfg=entrySpec(t);const range=cfg.numeric?`<div class="limit-panel"><div class="limit-header"><strong>冻结限度 ${cfg.limit}</strong><span id="range-tag" class="tag green">限度内 · 录入参考</span></div><div class="limit-scale"><i id="limit-pointer" class="limit-pointer"></i></div><div class="scale-labels">${cfg.labels.map(label=>`<span>${label}</span>`).join('')}</div></div><p id="range-note" class="state-note">数值与限度对照仅作录入参考，正式判定由 LIMS 计算。</p>`:`<div class="limit-panel qualitative"><div class="limit-header"><strong>冻结判定：${cfg.limit}</strong><span class="tag blue">按标准判定</span></div><p class="state-note">请依据原始记录选择或填写“符合规定 / 不符合规定”，并保留必要说明。</p></div>`;return `<div class="panel"><div class="panel-head"><h2>${t.material} · ${t.item}</h2>${stateTag(t.status)}</div><p class="muted">${t.sample}　/　批次 ${t.batch}　/　${t.id}</p>${processStrip(1)}</div><form id="entry-form"><div class="result-layout"><div><section class="panel"><div class="panel-head"><h2>填写检验结果</h2><span class="pill-check">${icon('lock')}标准已冻结</span></div><div class="method-card">${icon('flask')}<div><strong>${cfg.method}</strong><small>质量标准 ${t.material==='原料药 A'?'ZL-A':'对应物料标准'} · 当前版本　/　请按原始记录填写</small></div></div><div class="form-grid"><label class="form-field">原始读数 <em>必填</em><input id="raw-value" name="raw" value="${escapeHtml(d.raw??cfg.raw)}" required inputmode="decimal"></label><label class="form-field">结果值 <em>必填</em><div class="input-unit"><input id="result-value" name="result" value="${escapeHtml(d.result??cfg.result)}" ${cfg.numeric?'type="number" step="0.01" inputmode="decimal"':'type="text"'} required><span>${cfg.unit}</span></div></label><label class="form-field full">检验仪器 / 编号<input name="instrument" value="${escapeHtml(d.instrument||'HPLC-03')}" placeholder="记录本次使用的仪器"></label></div>${range}<label class="form-field full" style="margin-top:18px">检验说明 / 异常说明<textarea name="comment" rows="3" placeholder="填写与本次检验有关的说明">${escapeHtml(d.comment||'')}</textarea></label></section><section class="panel"><div class="panel-head"><h2>原始记录与附件</h2><span class="view-count">演示附件</span></div><button type="button" class="record-button" data-action="record">${icon('file')}<span><strong>${t.item}原始记录</strong><small>${t.sample} · 查看原始记录示意</small></span>${icon('chevron')}</button></section></div><aside><section class="panel"><h2>样品与检验依据</h2><dl class="context-list"><div><dt>样品编号</dt><dd>${t.sample}</dd></div><div><dt>批次</dt><dd>${t.batch}</dd></div><div><dt>检验项目</dt><dd>${t.item}</dd></div><div><dt>分析员</dt><dd>${t.owner}</dd></div><div><dt>标准版本</dt><dd>${t.material==='原料药 A'?'ZL-A · 第3版':'对应物料标准'}</dd></div><div><dt>截止时间</dt><dd>${t.due}</dd></div></dl>${quiet('查看样品上下文',`type="button" data-detail="${t.sample}" data-kind="samples"`)}</section><section class="panel"><h2>签署进度</h2>${signature('检验员 A','正在录入','blue')}${signature('复核员','等待提交','')}${signature('批准人','等待复核','')}<p class="note">复核人与检验人不同；批准人与检验人、复核人均不同。</p></section></aside></div><div class="action-bar"><p id="save-hint">${state.draftTime?'本页暂存于 '+state.draftTime:'填写完成后，先核对再提交'}</p><div class="actions">${btn('暂存本页','type="button" data-action="save"',false,'save')}${btn('核对并提交','type="submit"',true,'check')}</div></div></form>`;}
function signature(name,desc,tone){return `<div class="signature"><span class="circle">${icon(tone==='green'?'check':'user')}</span><div>${name}<small>${desc}</small></div>${tag(tone==='green'?'已完成':tone==='blue'?'当前':'待处理',tone)}</div>`;}
function referenceDetail(t){return `<div class="note">${t.sample} · 批次 ${t.batch} · ${t.item}</div><dl class="context-list"><div><dt>原始值</dt><dd>${t.raw||'演示原始记录'}</dd></div><div><dt>结果值</dt><dd class="result-value">${t.result||'待录入'} ${t.item==='含量测定'?'%':''}</dd></div><div><dt>冻结限度</dt><dd>${t.item==='含量测定'?'98.00% – 102.00%':'按项目冻结标准'}</dd></div><div><dt>检验人</dt><dd>${t.owner}</dd></div><div><dt>当前状态</dt><dd>${stateTag(t.status)}</dd></div></dl><div class="timeline"><div>样品登记<small>2026-09-29 · 演示时间</small></div><div>检验人录入原始记录<small>分析员 A</small></div>${t.log.map(l=>`<div>${escapeHtml(l)}<small>本次设计演示</small></div>`).join('')}</div>`;}
function review(){const pending=tasks.filter(t=>state.persona==='qa'?t.status==='已复核':['已提交','OOS候选'].includes(t.status));return `<div class="review-panel-note">${state.persona==='analyst'?'当前是检验员视角，可查看已提交记录。可在顶部切换为复核员或质量人员体验对应审阅界面。':state.persona==='reviewer'?'当前是复核员视角：核对结果及依据后，填写复核意见。':'当前是质量人员视角：核对已复核记录及签署后，再形成批准意见。'}</div><section class="panel"><div class="panel-head"><h2>${state.persona==='qa'?'等待批准':'等待复核'}</h2><span class="view-count">${pending.length} 项</span></div>${pending.map(t=>`<article class="task-row"><span class="sample-icon">${icon('shield')}</span><div><h3>${t.material} · ${t.item} ${stateTag(t.status)}</h3><p>${t.sample} · ${t.owner} · ${t.due}</p></div><div>${btn('查看检验依据',`data-review="${t.id}"`,true)}</div></article>`).join('')||empty('当前没有待处理记录','已完成的签署可以在受控台账中查看。','ledger','查看受控台账')}</section>`;}
function ledger(){const list=tasks.filter(t=>t.result);const chosen=list.find(t=>t.id===state.ledger)||list[0];return `<div class="toolbar"><span class="tag">结果与签署 · 只读追溯</span>${quiet('查阅审计追踪','data-page="audit"')}</div><div class="ledger-layout ${state.tab==='detail'?'show-detail':''}"><div class="ledger-list">${list.map(t=>`<button class="ledger-card ${chosen.id===t.id?'selected':''}" data-ledger="${t.id}"><header><strong>${t.id.replace('TJ','JG')}</strong>${stateTag(t.status==='OOS候选'?'已提交':t.status)}</header><h3>${t.material} · ${t.item}</h3><p>${t.sample} · 批次 ${t.batch}</p><p>检验员 A　<span>${t.result}${t.item==='含量测定'?' %':''}</span></p></button>`).join('')}</div><section class="panel ledger-detail"><button class="btn quiet ledger-back" data-action="ledger-back">${icon('arrow-left')}返回结果列表</button><div class="panel-head"><h2>${chosen.id.replace('TJ','JG')} · 受控记录</h2>${icon('lock')}</div>${referenceDetail(chosen)}${quiet('原始记录','data-action="record"')}<p class="note">已批准结果保持只读。修订、审计与内容指纹在对应领域中追溯。</p></section></div>`;}
function render(){renderNav();main.innerHTML=header();if(state.viewState!=='data'){main.innerHTML+=state.viewState==='loading'?'<div class="panel"><div class="skeleton" role="status" aria-label="正在加载"></div><p class="note">正在加载当前工作集…</p></div>':state.viewState==='error'?`<section class="panel">${empty('暂时无法加载实验室工作台','请稍后重试。你已填写的本页演示内容会保留。') }<div class="actions" style="justify-content:center">${btn('重新加载','data-action="recover"',true)}</div></section>`:`<section class="panel">${empty('当前范围内暂无待办','可以查看全部样品，或登记新的样品。','samples','查看样品台账')}</section>`;}else{main.innerHTML+=({dashboard, tasks:taskBoard,samples,register,results,entry:entryV2,review,ledger}[state.page]||(()=>window.LimsModules?window.LimsModules.render(state.page,state.tab):empty('页面正在准备','请稍后重新打开。')))();}hydrateIcons();if(state.page==='entry'&&state.viewState==='data')updateRange();document.title=`${titles[state.page]||'今日工作'} · 海滨 LIMS 设计原型`;}
function updateRange(){const input=document.getElementById('result-value');const t=tasks.find(t=>t.id===state.selected)||tasks[0];const cfg=entrySpec(t);const tagEl=document.getElementById('range-tag');if(!input||!tagEl||!cfg.numeric)return;const v=Number(input.value),valid=input.value.trim()!==''&&Number.isFinite(v),inside=valid&&v>=cfg.min&&v<=cfg.max;tagEl.textContent=!valid?'请填写结果值':inside?'限度内 · 录入参考':'超出限度 · 请核对';tagEl.className='tag '+(!valid?'amber':inside?'green':'red');document.getElementById('range-note').textContent=inside?'数值与限度对照仅作录入参考，正式判定由 LIMS 计算。':'请核对原始记录与结果值；如确认无误，填写异常说明并提交给后续质量流程。';document.getElementById('limit-pointer').style.left=Math.max(0,Math.min(100,(v-(cfg.min-1))/((cfg.max-cfg.min)+2)*100))+'%';}
function saveDraft(){const form=document.getElementById('entry-form');if(!form)return;state.draft[state.selected]=Object.fromEntries(new FormData(form));state.draftTime=new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});document.getElementById('save-hint').textContent='本页暂存于 '+state.draftTime;toast('已暂存当前页面，刷新后演示数据会重置');}
function isOutOfLimit(t,d){const cfg=entrySpec(t);if(!cfg.numeric)return String(d.result||'').trim()==='不符合规定';const value=Number(d.result);return !Number.isFinite(value)||value<cfg.min||value>cfg.max;}
function details(kind,title){const t=tasks.find(t=>t.sample===title)||tasks.find(t=>t.id===state.selected)||tasks[0];const modules={reports:['检验报告（COA）','报告审核、发布与归档状态由质量人员处理。'],specs:['质量标准','查阅版本、检验项目与冻结限度；维护动作需管理授权。'],retention:['留样记录','可沿留样编号追溯登记、观察、使用与处理记录。'],stability:['稳定性记录','查看对应方案、时间点、取样记录和结果。'],audit:['审计详情','只读查看操作、对象、时间与前后变化。']};let html;if(kind==='samples')html=`<div class="sample-label"><header>海滨实验室 · 样品标签</header><h3>${t.material}</h3><p>${t.sample} · 批号 ${t.batch}</p><div class="barcode" aria-hidden="true"></div></div><dl class="context-list"><div><dt>标准</dt><dd>ZL-A · 第 3 版</dd></div><div><dt>项目进度</dt><dd>${t.progress} / ${t.total}</dd></div><div><dt>当前检验项目</dt><dd>${t.item}</dd></div></dl>${processStrip(1)}<div class="actions">${btn('查看检验任务','data-page="tasks"',true)}</div>`;else{const m=modules[kind]||['记录详情','查阅对应业务记录。'];html=`<div class="note">${m[0]} · 演示记录</div><h3>${escapeHtml(title)}</h3><dl class="context-list"><div><dt>物料</dt><dd>原料药 A</dd></div><div><dt>关联批次</dt><dd>26092901</dd></div><div><dt>记录性质</dt><dd>只读设计预览</dd></div></dl><p class="note">${m[1]}</p><div class="timeline"><div>记录创建<small>演示记录 · 2026-09-28</small></div><div>关联检验依据<small>对应样品与标准快照</small></div></div>`;}openDialog(title,html);}
function record(){openDialog('检验原始记录 · 示意',`<div class="note">示意图用于展示附件的阅读位置，不代表仪器真实采集结果。</div><h3>含量测定 · 色谱图</h3><svg class="chromatogram" viewBox="0 0 500 120" role="img" aria-label="色谱峰与基线示意"><path d="M25 10v90h450" fill="none" stroke="#bdcfc2"/><path d="M25 95H90l7-12 6 12h70l10-13 5-58 5 58 8 13h110l8-16 7 16h145" fill="none" stroke="#348d74" stroke-width="2"/></svg><div class="chart-labels"><span>响应值</span><span>保留时间 / 分钟</span></div><dl class="context-list"><div><dt>记录关联</dt><dd>YP-0929-001</dd></div><div><dt>原始读数</dt><dd>0.4982</dd></div><div><dt>结果值</dt><dd>99.40%</dd></div></dl>`);}
function reviewDialog(id){const t=tasks.find(t=>t.id===id);const can=state.persona==='reviewer'&&['已提交','OOS候选'].includes(t.status)||state.persona==='qa'&&t.status==='已复核';openDialog('核对结果 · '+t.id,`${referenceDetail(t)}${t.status==='OOS候选'?'<p class="note red">超标候选须进入质量核查。本演示不提供解除锁定或直接批准。</p>':''}${can&&t.status!=='OOS候选'?`<label class="form-field">${state.persona==='qa'?'批准':'复核'}意见<textarea id="review-comment" rows="3" placeholder="填写核对依据与意见"></textarea></label><div class="actions">${btn('关闭','data-action="close-dialog"')}${btn(state.persona==='qa'?'确认批准（演示）':'确认复核（演示）',`data-sign="${t.id}"`,true)}</div>`:'<p class="note">当前为只读记录。可查看检验依据与签署进度。</p>'}`);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){if(dialog.open)closeDialog();navigate(b.dataset.page,{status:b.dataset.filter||'全部状态',tab:b.dataset.tabTarget||''});return;}if(b.dataset.task){const t=tasks.find(t=>t.id===b.dataset.task);state.selected=t.id;if(['已分配','检验中'].includes(t.status)&&state.persona==='analyst'){if(t.status==='已分配'){t.status='检验中';t.log.push('检验员 A 开始检验');}navigate('entry');}else{openDialog('检验记录 · '+t.id,referenceDetail(t)+`<div class="actions">${btn('查阅台账','data-page="ledger"')}</div>`);}return;}if(b.dataset.status){state.status=b.dataset.status;writeHash();render();return;}if(b.dataset.tab){state.tab=b.dataset.tab;writeHash();render();return;}if(b.dataset.detail){details(b.dataset.kind,b.dataset.detail);return;}if(b.dataset.review){reviewDialog(b.dataset.review);return;}if(b.dataset.ledger){state.ledger=b.dataset.ledger;state.tab='detail';render();return;}if(b.dataset.sign){const t=tasks.find(t=>t.id===b.dataset.sign);const allowed=(state.persona==='reviewer'&&t.status==='已提交')||(state.persona==='qa'&&t.status==='已复核');if(!allowed){toast('当前身份或状态不支持此操作');return;}const comment=document.getElementById('review-comment').value.trim();if(!comment){document.getElementById('review-comment').focus();toast('请先填写核对依据与意见');return;}t.status=state.persona==='qa'?'已批准':'已复核';t.log.push((state.persona==='qa'?'质量人员 C 批准':'复核员 B 复核')+'：'+comment);closeDialog();render();toast('演示签署已完成，结果状态已更新');return;}switch(b.dataset.action){case'close-dialog':closeDialog();break;case'record':record();break;case'save':saveDraft();break;case'urgent':state.urgent=!state.urgent;render();break;case'reset':state.q='';state.status='全部状态';state.urgent=false;writeHash();render();break;case'ledger-back':state.tab='';render();break;case'recover':state.viewState='data';render();break;case'reminders':openDialog('今日提醒',`<div class="next-event"><div class="event-date"><b>16</b>今天</div><div><h3>含量测定 · 临近截止</h3><p>原料药 A · YP-0929-001</p>${quiet('继续检验','data-task="TJ-026"')}</div></div><div class="next-event"><div class="event-date"><b>14</b>今天</div><div><h3>稳定性 · 6 月取样</h3>${quiet('查看取样计划','data-page="stability" data-tab-target="schedule"')}</div></div>`);break;case'portal':openDialog('HBOS 工作台',`<p>正式前台从这里返回同源的 HBOS 工作台。本次设计评审保持在独立原型中。</p><div class="actions">${btn('继续查看原型','data-action="close-dialog"',true)}</div>`);break;case'preview-settings':openDialog('设计评审工具',`<p>请选择展示状态。原型动作只在当前页面会话中演示，刷新即可重置。</p><div class="actions">${['data','empty','error','loading'].map((s,i)=>btn(['数据态','无数据态','服务错误','加载态'][i],`data-demo-state="${s}"`,s===state.viewState)).join('')}</div><p class="note">品牌原图、中文导航、样品流程、结果限度提示与完整领域入口是本版审核重点。</p>`);break;case'confirm-submit':{const t=tasks.find(t=>t.id===state.selected);if(t.status!=='检验中'){closeDialog();return;}const d=state.draft[t.id];t.result=d.result;t.raw=d.raw;t.status=isOutOfLimit(t,d)?'OOS候选':'已提交';t.log.push('检验员 A 提交结果');closeDialog();navigate('tasks',{status:t.status});toast(t.status==='OOS候选'?'演示结果已提交，标记为超标候选':'演示结果已提交，等待复核');break;}}if(b.dataset.demoState){state.viewState=b.dataset.demoState;closeDialog();render();}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;if(form.id==='global-search'||form.id==='list-search'){const q=new FormData(form).get('q').trim();if(form.id==='global-search'){navigate('tasks',{q});}else{state.q=q;writeHash();render();}return;}if(form.id==='register-form'){const values=new FormData(form);openDialog('核对样品登记信息',`<p>物料：<strong>${escapeHtml(values.get('material'))}</strong></p><p>批次：<strong>${escapeHtml(values.get('batch'))}</strong></p><div class="note">这是登记确认的设计演示，未新增真实样品。</div><div class="actions">${btn('返回修改','data-action="close-dialog"')}${btn('完成演示','data-page="samples"',true)}</div>`);return;}if(form.id==='entry-form'){saveDraft();const d=state.draft[state.selected];const t=tasks.find(t=>t.id===state.selected);if(isOutOfLimit(t,d)&&!d.comment.trim()){toast('结果超出限度，请填写异常说明');form.elements.comment.focus();return;}const cfg=entrySpec(t);openDialog('提交前，再核对一次',`<p><strong>${t.material} · ${t.item}</strong></p><p class="muted">${t.sample} · 批次 ${t.batch}</p><dl class="context-list"><div><dt>结果值</dt><dd class="result-value">${escapeHtml(d.result)} ${cfg.unit}</dd></div><div><dt>冻结限度</dt><dd>${cfg.limit}</dd></div><div><dt>下一步</dt><dd>等待独立复核</dd></div></dl><p class="note">本次提交只演示状态变化，不写入业务系统。</p><div class="actions">${btn('返回修改','data-action="close-dialog"')}${btn('确认提交（演示）','data-action="confirm-submit"',true)}</div>`);}});
document.addEventListener('input',e=>{if(e.target.id==='result-value')updateRange();});
document.addEventListener('change',e=>{if(e.target.id==='status-select'){state.status=e.target.value;writeHash();render();}if(e.target.id==='persona'){state.persona=e.target.value;document.getElementById('identity-label').textContent=e.target.options[e.target.selectedIndex].text;document.querySelector('.avatar').textContent=state.persona==='analyst'?'检':state.persona==='reviewer'?'复':'质';if(state.page==='entry')navigate('review');else render();}});
dialog.addEventListener('cancel',()=>{if(lastFocus?.isConnected)lastFocus.focus();});
function fromHash(){const [page,query]=location.hash.slice(1).split('?');if(titles[page])state.page=page;const params=new URLSearchParams(query);if(states.includes(params.get('status')))state.status=params.get('status');state.tab=params.get('tab')||'';state.q=params.get('q')||'';render();}
window.addEventListener('hashchange',fromHash);fromHash();
/* 记录示意跟随当前检验项目，避免水分、鉴别等项目误显示为含量色谱图。 */
function recordV2(){const t=tasks.find(t=>t.id===state.selected)||tasks[0];const cfg=entrySpec(t);const chart=cfg.numeric?`<svg class="chromatogram" viewBox="0 0 500 120" role="img" aria-label="${escapeHtml(t.item)}原始曲线示意"><path d="M25 10v90h450" fill="none" stroke="#bdcfc2"/><path d="M25 95H90l7-12 6 12h70l10-13 5-58 5 58 8 13h110l8-16 7 16h145" fill="none" stroke="#348d74" stroke-width="2"/></svg><div class="chart-labels"><span>响应值</span><span>保留时间 / 分钟</span></div>`:`<div class="qualitative-record"><span class="tag blue">原始记录示意</span><strong>${t.item}：符合规定</strong><p class="muted">按检验方法记录观察条件、样品外观与判定依据。</p></div>`;openDialog('检验原始记录 · '+t.item,`<div class="note">示意图用于展示附件的阅读位置，不代表仪器真实采集结果。</div><h3>${t.item} · 原始记录</h3>${chart}<dl class="context-list"><div><dt>记录关联</dt><dd>${t.sample}</dd></div><div><dt>原始读数</dt><dd>${t.raw||'待录入'}</dd></div><div><dt>结果值</dt><dd>${t.result||'待录入'} ${cfg.unit}</dd></div></dl>`);}
record=recordV2;
function detailsV2(kind,title){const t=tasks.find(t=>t.sample===title)||tasks.find(t=>t.id===state.selected)||tasks[0];if(kind==='samples'){openDialog(title,`<div class="sample-label"><header>海滨实验室 · 样品标签</header><h3>${t.material}</h3><p>${t.sample} · 批号 ${t.batch}</p><div class="barcode" aria-hidden="true"></div></div><dl class="context-list"><div><dt>标准</dt><dd>${t.material==='原料药 A'?'ZL-A · 第 3 版':'对应物料标准'}</dd></div><div><dt>项目进度</dt><dd>${t.progress} / ${t.total}</dd></div><div><dt>当前检验项目</dt><dd>${t.item}</dd></div></dl>${processStrip(1)}<div class="actions">${btn('查看检验任务','data-page="tasks"',true)}</div>`);return;}const labels={reports:['检验报告（COA）','报告审核、发布与归档状态由质量人员处理。'],specs:['质量标准','查阅版本、检验项目与冻结限度；维护动作需管理授权。'],retention:['留样记录','沿留样编号追溯登记、观察、使用与处理记录。'],stability:['稳定性记录','查看对应方案、时间点、取样记录和结果。'],audit:['审计详情','只读查看操作、对象、时间与前后变化。']};const info=labels[kind]||['领域记录','查阅对应业务记录。'];openDialog(title,`<div class="note">${info[0]} · 设计预览</div><h3>${escapeHtml(title)}</h3><dl class="context-list"><div><dt>关联对象</dt><dd>${escapeHtml(title)}</dd></div><div><dt>记录性质</dt><dd>只读设计预览</dd></div><div><dt>数据来源</dt><dd>对应领域记录（演示）</dd></div></dl><p class="note">${info[1]}</p><div class="timeline"><div>记录创建<small>演示记录 · 2026-09-28</small></div><div>关联检验依据<small>按页面入口保留领域上下文</small></div></div>`);}
details=detailsV2;
document.addEventListener('click',e=>{if(dialog.open&&e.target.closest('[data-task]'))closeDialog();});
